from pathlib import Path
import json,hashlib,shutil
A=Path(__file__).resolve().parent;L=A.parents[1];C=L/'canonical-proposal/v1';M=L.parents[4]
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,v):(A/n).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
A.mkdir(parents=True,exist_ok=True)
manifest=read(C/'record-manifest.json');records=[]
for x in manifest['records']:
 p=Path(x['path']);assert sha(p)==x['sha256'];r=read(p)
 if r['operations']:records.append(r)
configs={}
def scene(oid,title,art,prose,notes=(),extra=(),**kw):
 configs[oid]={'title':title,'art':art,'prose':prose,'notes':[{'label':k,'value':v} for k,v in notes],'extra_measurements':list(extra),**kw}
scene('a-dissolve-filter','Bulk A · precursor dissolution and filtration','dissolve','Dissolve the two salts in DMF, then filter to obtain a clear precursor solution. The diagram shows a generic filter and receiver; the paper does not specify their construction.',[('Whole preparation','All three charges refer to this bulk-A precursor preparation.'),('Filtration','Filter specification and vessel are not reported.')],variant='Bulk A')
scene('b-dissolve-filter','Bulk B · the reported salt-ratio variant','dissolve','Use 1 mmol tetrapropylammonium chloride in the otherwise inherited crystal-growth procedure. The SbCl₃ and DMF charges belong to the source’s explicit variant, not an independently optimized recipe.',[('Inherited fields','SbCl₃ and DMF charges follow the same stated procedure as bulk A.'),('Filtration','Filter specification and vessel are not reported.')],variant='Bulk B')
scene('a-evaporate','Bulk A · slow solvent evaporation','evaporate','Slowly evaporate the solvent at room temperature for four days and collect bulk A crystals. The outlined crystal shapes explain solid formation without claiming measured morphology.',[('Temperature','Room temperature; no numeric value is supplied.'),('Recovered material','Bulk A: (C₁₂H₂₈N)₂SbCl₅.'),('Unreported','Evaporation vessel, humidity and isolated yield.')],variant='A')
scene('b-evaporate','Bulk B · inherited crystal-growth conditions','evaporate','The source variant inherits four days of slow evaporation at room temperature and yields bulk B. It remains distinct from the bulk-A crystal and from the nanocrystal preparation.',[('Temperature','Room temperature; no numeric value is supplied.'),('Recovered material','Bulk B: (C₁₂H₂₈N)SbCl₄.'),('Inheritance','Duration and evaporation conditions follow the stated bulk-A procedure.')],variant='B')
scene('nc-dissolve-filter','Nanocrystals · prepare the full precursor stock','dissolve','Dissolve the full salt charges in DMF and filter clear. The solvent charge is not a separately measured final stock volume; only a later aliquot enters the precipitation step.',[('Whole stock','These charges prepare the stock, not the aliquot used in the next operation.'),('Volume basis','2000 µL is DMF charged; final solution volume is unreported.'),('Unreported','Filtration details and preparation temperature.')],variant='NC stock')
scene('nc-inject','Nanocrystals · rapid aliquot injection','inject','Rapidly inject the precursor-solution aliquot into vigorously stirred toluene and oleic acid. No heater or bath is added: the source supplies no nanocrystal growth temperature.',[('Transfer','Only the stated precursor aliquot is injected; the full stock is not consumed.'),('Mixing','Rapid injection; vigorous stirring. Numerical rates are not reported.'),('Unreported','Temperature, growth/aging duration and injection equipment.')])
scene('nc-centrifuge','Nanocrystals · centrifuge and recover powder','centrifuge','Centrifuge the crude solution and collect nanocrystal powders. The product fraction is the recovered solid. No wash, drying or redispersion stage is supplied by this operation.',[('Retained fraction','Nanocrystal powder / collected solid.'),('Unreported','Rotor radius/RCF, washing, drying, yield and redispersion.')])
scene('film-blend','Composite films · prepare the five mass-ratio mixtures','blend','Blend the blue phosphor and yellow-emitting A nanocrystals in polystyrene/toluene and stir. The five blue/yellow mass ratios describe separate formulations, including the two pure-component controls.',[('Components','Blue: BaMgAl₁₀O₁₇:Eu²⁺; yellow: A nanocrystals.'),('Unreported','Absolute masses, PS concentration and toluene volume.')],extra=[('lian2021-composite-mixing-q'+str(i),'Blue/yellow mass ratio · formulation '+str(i)) for i in range(1,6)])
scene('film-cast','Composite films · cast, evaporate and peel','cast-peel','Drop-cast the mixture onto glass and slowly evaporate the solvent in a fume hood. Peel the flexible composite film from the glass; the film is retained and the glass remains a separate support.',[('Evaporation','Slow solvent evaporation in a fume hood.'),('Retained fraction','Peeled composite film; glass is the separated support.'),('Unreported','Casting amount, drying time/temperature and film dimensions/thickness.')])
scene('spin-feed','Spin-coated film · prepare a separate precursor solution','dissolve','Dissolve the salts in DMF and filter clear for the precursor spin-coating route. This solution does not inherit the nanocrystal/phosphor/polystyrene composite formulation.',[('Whole solution','Full precursor preparation; a later 200 µL aliquot is used for coating.'),('Scope','Salt/DMF route; no PS, oleic acid or phosphor is added.'),('Unreported','Filtration details and final solution volume.')],variant='Spin-coat stock')
scene('spin-deposit','Spin-coated film · deposit, then anneal','spin-anneal','Apply the stated precursor aliquot to glass, spin-coat, and then anneal. The heater symbol denotes the reported thermal treatment without specifying an unreported hotplate or oven.',[('Order','Spin coating precedes annealing.'),('Retained material','Precursor-derived film on glass; no peeling is stated for this route.'),('Unreported','Annealing atmosphere, heating apparatus and film thickness.')])
scene('bulk-xray','Bulk crystals · diffraction acquisition','diffraction','Acquire PXRD and single-crystal XRD as distinct diffraction measurements. The source identifies the instruments; the beam/detector sketches are explanatory and contain no synthetic diffraction pattern.',[('PXRD instrument','PANalytical B.V. x’pert3.'),('SCXRD instrument','Rigaku XtaLAB PRO MM007HF; Cu Kα; room temperature in methods.'),('Specimen scope','Bulk A and B remain separate crystal contexts; detailed refinement temperatures are in Table S1.'),('Unreported','Scan settings and numeric wavelength in this methods passage.')])
scene('bulk-xps-tga','Bulk crystals · separate XPS and TGA acquisitions','xps-tga','Use the XPS and TGA instruments for separate analyses. Nitrogen is assigned only to TGA; it is not an XPS atmosphere or a synthesis condition.',[('XPS instrument','Shimadzu Kratos AXIS SUPRA+.'),('TGA instrument','PerkinElmer Pyris1, under N₂.'),('Unreported','TGA ramp and N₂ flow; XPS atmosphere/pressure.')])
scene('bulk-optics','Bulk crystals · PL, PLE and lifetime acquisition','optics','Measure steady-state PL/PLE, time-resolved decay and temperature-dependent spectra with the stated spectrofluorometer and TCSPC system. Instrument capability does not assign one temperature or one batch to all observations.',[('Instrument','Edinburgh FLS980 with TCSPC and liquid-nitrogen cooler.'),('Specimens','Bulk A and bulk B retain separate sample contexts.'),('Scope','Cooling is an acquisition capability, not a synthesis atmosphere.')],variant='Bulk A / bulk B')
scene('bulk-plqe','Bulk A · baseline and integrating-sphere PLQE','sphere','First acquire the excitation baseline, then place the bulk A single crystals into the calibrated integrating sphere for PLQE. Crystal loading and optical geometry are not quantified.',[('Instrument','Zolix OmniFluo; calibrated Labsphere integrating sphere.'),('Order','Baseline first; then the crystal specimen.'),('Unreported','Sample mass and detailed loading geometry.')],variant='Bulk A crystals')
scene('nc-tem','Nanocrystals · EFTEM acquisition','tem','Acquire nanocrystal images with the FEI Tecnai G2 F30 in EFTEM mode. The column sketch describes acquisition only; the paper does not report a TEM grid material or deposition procedure.',[('Instrument','FEI Tecnai G2 F30; EFTEM mode.'),('Unreported','Grid, deposition/preparation, counting protocol and physical cross-assay batch join.'),('Evidence','Original images are separate; no micrograph or SAED pattern is synthesized.')])
scene('nc-optics','Nanocrystals · PL, PLE and decay acquisition','optics','Acquire nanocrystal PL/PLE and decay measurements within the reported spectroscopy methods. The non-PLQE sample-state details are not fully specified and are not silently equated with dried powder or a particular colloid.',[('Instrument','Edinburgh FLS980 / TCSPC methods.'),('Unreported','Assay-specific sample state and exact physical-batch links.'),('Scope','General cooling capability does not assign a temperature to this operation.')],variant='Nanocrystal context')
scene('nc-plqe','Nanocrystal powder · integrating-sphere PLQE','sphere','Measure the baseline, then the dried nanocrystal powder in the calibrated integrating sphere. The reported powder PLQE does not establish the same result for a dispersed colloid.',[('Instrument','Zolix OmniFluo; calibrated Labsphere integrating sphere.'),('Specimen','Dried nanocrystal powder; no colloid PLQE identity is inferred.'),('Unreported','Drying procedure and sample mass.')],variant='Dried NC powder')
scene('film-pl','Films · source-scoped PL acquisition','film-optics','The source uses a Zolix OmniFluo for film PL. The composite and precursor spin-coated films are separate preparations, not two states of one assumed physical specimen.',[('Instrument','Zolix OmniFluo film PL methods.'),('Specimen separation','NC/phosphor/PS composite film versus precursor spin-coated film.'),('Unreported','Film thickness and detailed optical geometry.')])
scene('beta-irradiate','Radioluminescence · electron-beam excitation','beta','Irradiate bulk A crystals and the nanocrystal composite film using the linear electron accelerator, then collect radioluminescence with the fibre spectrometer. The diagram does not assign all five blend ratios to this test.',[('Excitation system','WASIK (USA) linear electron accelerator.'),('Detection','Ocean Optics USB2000+ fibre spectrometer.'),('Specimens','Bulk A and NC composite film; the tested film’s exact blend ratio is not identified.'),('Unreported','Exposure time, total dose, absolute yield and detection limit.')])
scene('dft-relax','DFT · separate calculations for compounds A and B','dft','Calculate electronic structure with VASP PAW/PBE and HSE06, relaxing both lattice constants and atomic positions to the reported force criterion. These are theoretical calculations; no relaxed coordinate file is supplied.',[('Method','VASP; PAW; PBE and HSE06.'),('Relaxation','Both lattice parameters and atomic positions.'),('Scope','A/B meshes retain their composition assignments; no nanocrystal coordinates are generated.')],extra=[('lian2021-dft-method-q3','Compound A k-point mesh'),('lian2021-dft-method-q2','Compound B k-point mesh')])
labels={'c12h28ncl_charge':'Tetrapropylammonium chloride charge','sbcl3_charge':'SbCl₃ charge','dmf_solvent_charge':'DMF solvent charge','sbcl3_inherited_charge':'SbCl₃ charge · inherited variant','dmf_inherited_solvent_charge':'DMF charge · inherited variant','evaporation_duration':'Evaporation duration','inherited_evaporation_duration':'Evaporation duration · inherited variant','precursor_solution_aliquot':'Precursor-solution aliquot','toluene_antisolvent':'Toluene antisolvent charge','oleic_acid_ligand':'Oleic acid charge','centrifuge_speed':'Centrifuge speed','centrifuge_duration':'Centrifuge duration','mixing_duration':'Mixing duration','spin_speed':'Spin-coating speed','spin_duration':'Spin-coating duration','annealing_temperature':'Annealing temperature','annealing_duration':'Annealing duration','baseline_and_plqe_excitation':'Baseline / PLQE excitation','plqe_excitation':'Powder PLQE excitation · outcome context','accelerating_voltage':'TEM accelerating voltage','electron_energy':'Electron energy','accelerator_power':'Accelerator power','dose_rate':'Dose rate','plane_wave_kinetic_cutoff':'Plane-wave kinetic-energy cutoff','force_stopping_criterion':'Force stopping criterion'}
bindings=[];params=0;extra=0
for r in records:
 for i,o in enumerate(r['operations']):
  c=configs[o['id']];c.update(record_id=r['record_id'],operation_pointer=f'/operations/{i}');c['measurement_rows']=[]
  for mid,label in c.pop('extra_measurements'):
   ix=next(j for j,m in enumerate(r['measurements']) if m['id']==mid);c['measurement_rows'].append({'measurement_id':mid,'pointer':f'/measurements/{ix}/value','label':label});extra+=1
  for k in o['parameters']:assert k in labels;params+=1
  bindings.append({'record_id':r['record_id'],'record_path':str(C/(r['record_id']+'.json')),'record_sha256':sha(C/(r['record_id']+'.json')),'operation_id':o['id'],'operation_pointer':f'/operations/{i}','inputs':o['inputs'],'outputs':o['outputs'],'retained_fraction':o['retained_fraction'],'canonical_description':o['description'],'source_evidence':o['evidence'],'human_prose':c['prose'],'art':c['art'],'measurement_rows':c['measurement_rows'],'binding_approved':False})
assert len(bindings)==len(configs)==21
data={'source_group':'lian2021','configs':configs,'parameter_labels':labels};save('scene-config.json',data);save('records.json',records);save('canonical-bindings.json',{'author':'/root/norberg2004_extract','status':'private_author_proposal','bindings':bindings,'counts':{'scenes':21,'parameters':params,'additional_context_fields':extra},'canonical_manifest_sha256':sha(C/'package-manifest.json')})
(A/'lian2021-protocol.mjs').write_text((A/'protocol-template.mjs').read_text(encoding='utf-8').replace('__CONFIG__',json.dumps(data,ensure_ascii=False,separators=(',',':'))),encoding='utf-8')
shutil.copyfile(M/'recipe-atlas/dist/quantity-value.mjs',A/'quantity-value.mjs')
print(json.dumps({'scenes':21,'parameters':params,'extra_fields':extra,'operation_records':len(records)}))
